import{_ as a}from"./chunks/settings-robot.pc.ko.GwDViD4u.js";import{_ as o}from"./chunks/log-bb-player.pc.ko.BXBA5pF-.js";import{_ as s,o as e,c as n,a5 as r}from"./chunks/framework.BjM_ivYE.js";const k=JSON.parse('{"title":"기술지원 요청","description":"","frontmatter":{"layout":"doc","outline":"deep","title":"기술지원 요청"},"headers":[],"relativePath":"ko/manual/support/index.md","filePath":"ko/manual/support/index.md","lastUpdated":1789720001000}'),d={name:"ko/manual/support/index.md"};function l(i,t,c,p,h,g){return e(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="기술지원-요청-c-s-·-a-s" tabindex="-1">기술지원 요청 (C/S · A/S) <a class="header-anchor" href="#기술지원-요청-c-s-·-a-s" aria-label="Permalink to &quot;기술지원 요청 (C/S · A/S)&quot;">​</a></h1><p>레인보우로보틱스 공식 지원 창구로 요청을 접수하는 방법입니다. <strong>스스로 확인하는 법 → 무엇을 준비하는지 → 로그 만드는 법 → 어디로 보내는지</strong> 순서로 되어 있습니다. 접수 창구 링크는 <strong><a href="#where-to-send">맨 아래</a></strong> 에 있습니다 — 준비물을 갖추고 접수하는 편이 훨씬 빠르게 해결되기 때문입니다.</p><div class="danger custom-block"><p class="custom-block-title">⚠ 안전이 걸린 상황이면 먼저 멈추세요</p><p>화재·연기·비정상 동작·부상 위험이 있으면 이 페이지를 읽기 전에 <a href="/RBQ/ko/guides/common/emo.html">비상 정지 및 복구</a>부터 수행하세요.</p></div><h2 id="before-you-ask" tabindex="-1">1. 먼저 스스로 확인하기 <a class="header-anchor" href="#before-you-ask" aria-label="Permalink to &quot;1. 먼저 스스로 확인하기 {#before-you-ask}&quot;">​</a></h2><p>이미 답이 있는 증상이 많습니다. 5분이면 확인됩니다.</p><ul><li><a href="/RBQ/ko/manual/troubleshooting/joystick-not-working.html">증상별 문제 해결</a> — 조이스틱 무반응, 카메라 안 나옴, 도킹 실패 등</li><li><a href="/RBQ/ko/manual/gui/dashboard.html">대시보드</a> — 배터리 전압, <code>IMU</code>·<code>CAN</code>·<code>FindPose</code>·<code>Control</code> 상태</li><li><a href="/RBQ/ko/manual/gui/logs.html">로그 · 블랙박스</a> — 그 시점에 어떤 오류가 올라왔는지</li></ul><p>확인한 내용은 버려지지 않습니다. <strong>아래 요청서의 &quot;이미 시도한 것&quot;에 그대로 적으면 됩니다.</strong></p><h3 id="ask-ai" tabindex="-1">AI에게 먼저 물어보기 <a class="header-anchor" href="#ask-ai" aria-label="Permalink to &quot;AI에게 먼저 물어보기 {#ask-ai}&quot;">​</a></h3><p>이 문서 사이트에는 <strong>매뉴얼 전체를 읽고 답하는 AI</strong>로 연결되는 버튼이 있습니다. 화면 <strong>상단바 왼쪽의 <code>AI에게 질문</code></strong> 을 누르면 됩니다 — 어느 페이지에서나 보입니다.</p><table tabindex="0"><thead><tr><th>무엇을 하나</th><th>매뉴얼 전문(<code>llms-full.txt</code>)을 근거로 삼도록 준비된 질문을 만들어, <strong>Claude</strong> 또는 <strong>ChatGPT</strong> 로 열어줍니다</th></tr></thead><tbody><tr><td>고르는 방법</td><td><code>Claude에서 열기</code> · <code>ChatGPT에서 열기</code> · <code>AI용 프롬프트 복사</code>(다른 AI에 붙여넣기)</td></tr><tr><td>비용</td><td>해당 AI 서비스의 계정이 필요합니다</td></tr></tbody></table><p><strong>이런 질문에 잘 맞습니다</strong> — &quot;페이로드 무게중심은 어디를 기준으로 재나요&quot;, &quot;STAIRS 모드와 Stairs 모션은 뭐가 다른가요&quot;, &quot;이 설정은 뭘 바꾸나요&quot; 처럼 <strong>매뉴얼 안에 답이 있는</strong> 질문. 여러 페이지에 흩어진 내용을 한 번에 물어볼 때 특히 빠릅니다.</p><div class="warning custom-block"><p class="custom-block-title">⚠ AI 답변을 그대로 믿지 마세요</p><p>AI는 <strong>틀린 답을 그럴듯하게</strong> 말할 수 있습니다. 특히 아래는 반드시 매뉴얼 원문이나 지원팀으로 확인하세요.</p><ul><li><strong>안전·정비 절차</strong> — 비상 정지, 배터리 취급, 분해·교체</li><li><strong>로봇을 실제로 움직이는 조작</strong> — 값을 넣기 전에 원문 확인</li><li><strong>고장 진단</strong> — AI는 로봇 상태를 볼 수 없습니다. 실제 고장은 아래 절차로 접수하세요</li><li><strong>최신 변경 사항</strong> — 문서에 아직 반영되지 않은 내용은 알지 못합니다</li></ul></div><h2 id="how-to-fill" tabindex="-1">2. 요청서에 넣을 것 <a class="header-anchor" href="#how-to-fill" aria-label="Permalink to &quot;2. 요청서에 넣을 것 {#how-to-fill}&quot;">​</a></h2><p>CS와 A/S 두 창구의 양식은 항목이 같습니다.</p><h3 id="product-info" tabindex="-1">제품 정보 <a class="header-anchor" href="#product-info" aria-label="Permalink to &quot;제품 정보 {#product-info}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>무엇을 넣나</th><th>어디서 확인하나</th></tr></thead><tbody><tr><td><strong>제품 유형</strong></td><td><code>RBQ 시리즈</code></td><td>—</td></tr><tr><td><strong>제품명</strong></td><td><code>RBQ10</code></td><td>—</td></tr><tr><td><strong>시리얼 번호</strong></td><td>로봇 고유 번호</td><td>허브 로봇 목록의 로봇 이름 아래·<code>로봇 설정</code> 제목, 또는 로봇 본체 라벨</td></tr><tr><td><strong>설치일</strong></td><td><code>연도.월.일</code> 형식</td><td>납품·설치 기록</td></tr><tr><td><strong>지역</strong></td><td>로봇이 있는 지역</td><td>—</td></tr><tr><td><strong>판매처</strong></td><td>구매한 대리점·담당자</td><td>구매 기록</td></tr><tr><td><strong>소프트웨어 사용 여부</strong></td><td><code>예</code> / <code>아니오</code></td><td>SDK·자체 프로그램으로 로봇을 제어 중이면 <code>예</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">📝 시리얼 번호를 앱에서 확인하는 법</p><p><strong>대시보드</strong> → <strong>시스템</strong> 카드 맨 위 <code>로봇 S/N</code> 행의 값입니다. 로봇이 알려주는 값이라 읽기만 되고 고칠 수 없으며, 로봇에 연결되어 있어야 보입니다. 허브 로봇 목록의 로봇 이름 아래와 <code>로봇 설정</code> 제목에서도 볼 수 있습니다.</p></div><h3 id="payload" tabindex="-1">장착한 페이로드 <a class="header-anchor" href="#payload" aria-label="Permalink to &quot;장착한 페이로드 {#payload}&quot;">​</a></h3><p><strong>로봇에 무엇을 올렸는지는 반드시 적어주세요.</strong> 보행이 불안정하거나 자꾸 넘어지는 증상은 페이로드의 질량·무게중심 값이 실제와 다를 때 가장 많이 생깁니다. 이 정보가 없으면 지원팀이 처음 되묻는 항목입니다.</p><p>적을 내용은 셋입니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>예</th></tr></thead><tbody><tr><td><strong>무엇을 올렸나</strong></td><td>PTZ 카메라, Livox LiDAR ×2, LTE/5G 모듈</td></tr><tr><td><strong>앱에 등록한 값</strong></td><td>장착 슬롯 <code>5 / 13</code> · 총 질량 <code>7.19 kg</code> · 무게중심 <code>(-0.006, 0, 0.173) m</code></td></tr><tr><td><strong>실물과 맞나</strong></td><td>값을 실측했는지, 아니면 기본값 그대로인지</td></tr></tbody></table><h4 id="where-to-read-payload" tabindex="-1">값을 확인하는 곳 <a class="header-anchor" href="#where-to-read-payload" aria-label="Permalink to &quot;값을 확인하는 곳 {#where-to-read-payload}&quot;">​</a></h4><p><strong>로봇 설정 › 페이로드 설정</strong>을 열면 13개 슬롯 중 무엇이 체크되어 있고 각각 어떤 값인지 보입니다. 목록 아래의 <strong>합계</strong>가 총 질량과 무게중심입니다.</p><figure><img src="'+a+`" alt="로봇 설정 › 페이로드 설정 — 슬롯과 합계"><figcaption style="text-align:center;">[ 체크된 슬롯과 값, 그리고 아래쪽 합계를 함께 캡처하면 가장 좋습니다 ]</figcaption></figure><p><strong>대시보드 › 구성</strong> 카드에서도 같은 값을 요약해서 볼 수 있습니다 — <code>장착 슬롯</code> · <code>총 질량</code> · <code>CoM X · Y · Z</code>. 어느 쪽이든 <strong>화면을 캡처해 첨부</strong>하면 그대로 전달됩니다.</p><div class="warning custom-block"><p class="custom-block-title">⚠ 짐을 뗐는데 체크가 남아 있지 않은지</p><p>장착물을 제거했으면 그 슬롯의 체크도 해제해야 합니다. 체크가 남아 있으면 로봇이 없는 무게를 계산에 넣어 보행이 불안정해집니다 — 실제로 잦은 원인입니다. 값 넣는 방법은 <a href="/RBQ/ko/manual/gui/settings.html#robot-parameters">로봇 설정 › 페이로드 설정</a>를 보세요.</p></div><p>페이로드를 새로 달거나 바꾼 뒤라면 <strong>ZMP 캘리브레이션을 했는지도 함께 적어주세요</strong> (<a href="/RBQ/ko/guides/add-on/zmp-calibration.html">ZMP 캘리브레이션</a>). 안 했다면 그것부터 해보시는 편이 빠를 수 있습니다.</p><h3 id="inquiry-content" tabindex="-1">문의 내용 쓰는 법 <a class="header-anchor" href="#inquiry-content" aria-label="Permalink to &quot;문의 내용 쓰는 법 {#inquiry-content}&quot;">​</a></h3><p><strong>&quot;안 됩니다&quot;만 적으면 반드시 되묻는 메일이 한 번 더 오갑니다.</strong> 아래 다섯 가지를 채우면 대개 첫 회신에서 원인이 좁혀집니다. 그대로 복사해 쓰세요.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[증상]</span></span>
<span class="line"><span>무엇이 어떻게 되는지 한 줄로. (예: WALK 로 전환하면 3초 뒤 로봇이 주저앉습니다)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[재현 방법]</span></span>
<span class="line"><span>1. 로봇을 평지에 놓고 자동 기동을 완료</span></span>
<span class="line"><span>2. STAND → WALK 전환</span></span>
<span class="line"><span>3. 왼쪽 조이스틱을 앞으로 밀면 3초 뒤 주저앉음</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[발생 시점·빈도]</span></span>
<span class="line"><span>2026-09-01 14:30 무렵부터. 10번 중 8번.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[소프트웨어 버전]</span></span>
<span class="line"><span>앱: 1.2609.0   로봇: 1.2609.0   (로봇 설정 › 소프트웨어 업데이트에서 확인)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[장착 페이로드]</span></span>
<span class="line"><span>PTZ 카메라 + Livox LiDAR ×2 + LTE/5G · 슬롯 5/13 · 총 7.19 kg</span></span>
<span class="line"><span>무게중심 (-0.006, 0, 0.173) m · 실측값 입력함 · ZMP 캘리브레이션 완료</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[이미 시도한 것]</span></span>
<span class="line"><span>- 로봇 재부팅 → 동일</span></span>
<span class="line"><span>- 페이로드 값 재설정 → 동일</span></span>
<span class="line"><span>- 매뉴얼의 &#39;로봇이 넘어졌을 때&#39; 절차 수행 → 복구는 되지만 재발</span></span></code></pre></div><p>특히 <strong>버전 두 개(앱·로봇)</strong> 는 빠뜨리기 쉬운데, 버전이 어긋나서 생기는 증상이 실제로 있어 가장 먼저 확인하는 항목입니다. <strong>로봇 설정 › 소프트웨어 업데이트</strong>에서 <code>이 앱 (GUI)</code> 와 <code>현재 로봇</code>의 <code>Version</code> 을 그대로 옮겨 적으면 됩니다.</p><h3 id="attachments" tabindex="-1">첨부파일 <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;첨부파일 {#attachments}&quot;">​</a></h3><p>양식은 파일을 <strong>한 개</strong> 받고, 받는 형식이 정해져 있습니다.</p><table tabindex="0"><thead><tr><th>받는 형식</th><th><code>.jpg</code> · <code>.jpeg</code> · <code>.png</code> · <code>.pdf</code> · <code>.zip</code></th></tr></thead></table><div class="warning custom-block"><p class="custom-block-title">⚠ 로그 파일은 그대로 못 올립니다</p><p><code>.log</code> · <code>.txt</code> · <code>.csv</code> 는 받지 않습니다. <strong><code>.zip</code> 으로 묶어서</strong> 올리세요. 붙일 것이 여러 개일 때도 하나의 zip 으로 묶습니다.</p></div><p>무엇을 붙이면 좋은지 순서대로입니다.</p><ol><li><strong>블랙박스 zip</strong> — 사고 전후의 자세·수치 기록. 가장 도움이 됩니다.</li><li><strong>페이로드 설정 화면 캡처</strong> — 위 <a href="#where-to-read-payload">값을 확인하는 곳</a> 참고.</li><li><strong>증상이 보이는 화면 캡처</strong> — 오류 메시지, 대시보드의 비정상 값.</li><li><strong>동영상</strong> — 용량이 크면 링크로 대신 보내고, 문의 내용에 주소를 적으세요.</li></ol><h3 id="contact" tabindex="-1">연락처와 동의 <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;연락처와 동의 {#contact}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>비고</th></tr></thead><tbody><tr><td>회사명 · 부서 · 이름</td><td>—</td></tr><tr><td>연락처</td><td><code>010-0000-0000</code> 형식</td></tr><tr><td>이메일</td><td><strong>회신이 오는 곳입니다.</strong> 오타가 나면 답을 못 받습니다</td></tr><tr><td>문의 경로</td><td><code>검색</code> · <code>뉴스&amp;기사</code> · <code>전시&amp;세미나</code> · <code>SNS</code> · <code>지인추천</code> · <code>기타</code></td></tr><tr><td>개인정보 수집·이용 동의</td><td><strong>동의해야 접수됩니다</strong></td></tr></tbody></table><h2 id="collect-logs" tabindex="-1">3. 첨부할 로그 만들기 <a class="header-anchor" href="#collect-logs" aria-label="Permalink to &quot;3. 첨부할 로그 만들기 {#collect-logs}&quot;">​</a></h2><p>로그는 <strong>RBQ 앱</strong>의 <strong>로그</strong> 화면에서 만듭니다. 이 화면은 메뉴에 없습니다 — 빨간 <strong>ERROR</strong> · <strong>FATAL</strong> 토스트나, 제어 홈 상단바의 경보 배지 팝오버에서 줄을 탭하면 열립니다. 화면 전체 설명은 <a href="/RBQ/ko/manual/gui/logs.html">로그 · 블랙박스</a>에 있습니다.</p><h3 id="blackbox-zip" tabindex="-1">블랙박스 zip — 가장 먼저 <a class="header-anchor" href="#blackbox-zip" aria-label="Permalink to &quot;블랙박스 zip — 가장 먼저 {#blackbox-zip}&quot;">​</a></h3><p>넘어짐·고장처럼 <strong>순간적인 이상</strong>에는 이것 하나가 가장 유용합니다. 그 시점의 자세·전압·관절 값이 로그와 함께 들어 있습니다.</p><ol><li><strong>로그 → Black Box</strong> 탭을 엽니다.</li><li><strong>DATE</strong> 와 <strong>SESSION</strong> 에서 문제가 난 날짜·시간대를 고릅니다.</li><li><strong>불러오기</strong> 를 눌러 기록을 올립니다.</li><li>재생 막대로 <strong>증상이 보이는 구간이 맞는지</strong> 확인합니다.</li><li><strong>zip 저장</strong> 을 누릅니다 — 그대로 첨부하면 됩니다.</li></ol><figure><img src="`+o+`" alt="Black Box 재생 화면"><figcaption style="text-align:center;">[ Black Box — DATE·SESSION 을 고르고 zip 저장 ]</figcaption></figure><h3 id="system-log" tabindex="-1">시스템 로그 <a class="header-anchor" href="#system-log" aria-label="Permalink to &quot;시스템 로그 {#system-log}&quot;">​</a></h3><p>지난 로그를 날짜별로 남길 때 씁니다.</p><ol><li><strong>로그 → System Log</strong> 탭에서 <strong>DATE</strong> 로 날짜를 고르고 <strong>불러오기</strong>.</li><li>레벨 필터에서 <strong><code>WARNING</code> · <code>ERROR</code> · <code>FATAL</code></strong> 만 남기면 볼 것이 확 줄어듭니다.</li><li><strong>저장</strong> 으로 파일을 내려받습니다.</li><li>내려받은 파일을 <strong>zip 으로 묶어</strong> 첨부합니다.</li></ol><h3 id="screenshot" tabindex="-1">화면 캡처 <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;화면 캡처 {#screenshot}&quot;">​</a></h3><p>증상을 다시 만들 수 있다면 이 방법이 가장 빠릅니다.</p><ol><li><strong>로그 → Real Time</strong> 탭을 엽니다.</li><li>증상을 <strong>한 번 재현</strong>합니다.</li><li>그 시점에 올라온 메시지를 <strong>화면 캡처</strong>합니다. 레벨·프로세스 필터로 관련 메시지만 추려 두면 읽기 좋습니다.</li></ol><div class="tip custom-block"><p class="custom-block-title">📝 재현이 안 될 때</p><p><strong>System Log</strong> 에서 문제가 난 날짜를 골라 그 시각 부근을 캡처하세요. 정확한 시각을 모르면 시간대만 알려주셔도 됩니다.</p></div><h3 id="zip-together" tabindex="-1">여러 개를 하나로 묶기 <a class="header-anchor" href="#zip-together" aria-label="Permalink to &quot;여러 개를 하나로 묶기 {#zip-together}&quot;">​</a></h3><p>첨부는 한 개만 되므로, 붙일 것이 여러 개면 묶습니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 리눅스 · macOS — 파일들을 한 폴더에 모은 뒤</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq-support-2026-09-01.zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 모을폴더/</span></span></code></pre></div><p>윈도우는 폴더에서 <strong>우클릭 → 압축(ZIP) 파일로 만들기</strong> 를 쓰면 됩니다. 파일 이름에 <strong>날짜와 시리얼 번호</strong>를 넣어두면 담당자가 찾기 쉽습니다.</p><h2 id="where-to-send" tabindex="-1">4. 접수하기 <a class="header-anchor" href="#where-to-send" aria-label="Permalink to &quot;4. 접수하기 {#where-to-send}&quot;">​</a></h2><p>준비가 끝났으면 아래에서 창구를 고릅니다. 창구가 두 개로 나뉘어 있고, <strong>잘못 고르면 담당 부서로 다시 넘어가느라 회신이 늦어집니다.</strong></p><table tabindex="0"><thead><tr><th>상황</th><th>창구</th></tr></thead><tbody><tr><td>사용법·기능·설정·사양이 궁금하다</td><td><strong><a href="https://rainbow-robotics.com/%EA%B3%A0%EA%B0%9D%EC%A7%80%EC%9B%90/%EA%B8%B0%EC%88%A0%EC%A7%80%EC%9B%90/cs%EA%B8%B0%EC%88%A0%EC%A7%80%EC%9B%90/" target="_blank" rel="noreferrer">CS 기술지원 요청하기</a></strong></td></tr><tr><td>고장·오류가 나서 <strong>점검이나 수리</strong>가 필요하다</td><td><strong><a href="https://rainbow-robotics.com/%EA%B3%A0%EA%B0%9D%EC%A7%80%EC%9B%90/%EA%B8%B0%EC%88%A0%EC%A7%80%EC%9B%90/a-s-%EC%A7%80%EC%9B%90/" target="_blank" rel="noreferrer">A/S 지원 요청하기</a></strong></td></tr></tbody></table><p>가르는 기준은 간단합니다 — <strong>로봇을 보내거나 사람이 가야 하면 A/S</strong>, 답변으로 끝나면 <strong>CS</strong>입니다. 판단이 애매하면 CS로 넣으세요. 내부에서 A/S로 넘겨 줍니다.</p><p>개발자용 창구도 따로 있습니다.</p><table tabindex="0"><thead><tr><th>창구</th><th>용도</th></tr></thead><tbody><tr><td><a href="https://github.com/RainbowRobotics/RBQ/issues" target="_blank" rel="noreferrer">GitHub Issues</a></td><td>재현 가능한 소프트웨어 버그</td></tr><tr><td><a href="https://github.com/RainbowRobotics/RBQ/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a></td><td>질문 · 기능 제안</td></tr><tr><td><a href="mailto:rbq.support@rainbow-robotics.com" target="_blank" rel="noreferrer">rbq.support@rainbow-robotics.com</a></td><td>비공개 · 비즈니스 · 라이선스</td></tr></tbody></table><h2 id="after" tabindex="-1">5. 접수한 뒤 <a class="header-anchor" href="#after" aria-label="Permalink to &quot;5. 접수한 뒤 {#after}&quot;">​</a></h2><ul><li>입력한 <strong>이메일로 회신</strong>이 옵니다. 스팸함도 함께 확인하세요.</li><li>회신에 이어서 답할 때는 <strong>같은 메일 스레드</strong>에 답장하세요. 새로 접수하면 이력이 갈라집니다.</li><li>추가 로그를 요청받으면 위 <a href="#collect-logs">첨부할 로그 만들기</a> 를 다시 수행해 보내면 됩니다.</li><li>로봇을 보내야 하는 경우 <a href="/RBQ/ko/guides/common/packing.html">포장</a> 절차를 따르세요.</li></ul><h2 id="see-also" tabindex="-1">함께 보면 좋은 곳 <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;함께 보면 좋은 곳 {#see-also}&quot;">​</a></h2><ul><li><a href="https://rainbow-robotics.com/%EA%B3%A0%EA%B0%9D%EC%A7%80%EC%9B%90/%EB%8C%80%EB%A6%AC%EC%A0%90-%EC%B0%BE%EA%B8%B0/" target="_blank" rel="noreferrer">대리점 찾기</a> — 가까운 판매·지원처</li><li><a href="https://rainbow-robotics.com/%EA%B3%A0%EA%B0%9D%EC%A7%80%EC%9B%90/%EC%9E%90%EB%A3%8C%EC%8B%A4/" target="_blank" rel="noreferrer">자료실</a> — 카탈로그·문서</li><li><a href="/RBQ/ko/manual/downloads/">다운로드</a> — 앱 · 로봇 소프트웨어 · CAD · 매뉴얼 PDF</li></ul>`,66)])])}const f=s(d,[["render",l]]);export{k as __pageData,f as default};
